INSERT INTO "daily_horoscopes" VALUES('835cd633-2db9-406f-a0b9-73fd38c9f9b4','leo','2026-04-30','The universe rewards courage; step beyond your comfort zone.','Romance shines bright; let your heart roar.','You are in the spotlight—own it with confidence.','Sunshine and stretching lift your mood.',81,'Turquoise','2026-04-30 03:47:49','en');
