INSERT INTO "tarot_daily" VALUES('f64c2e40-a075-4d8c-b638-6ca0436df158','2026-05-01','Asia/Ulaanbaatar','leo','{"copyRev":3,"date":"2026-05-01","timezone":"Asia/Ulaanbaatar","sign":"leo","card_of_the_day":{"name":{"en":"Wheel of Fortune","mn":"Хувь тавилангийн хүрд"},"arcana":"Major","orientation":"Upright","core_meaning":{"en":"Cycles, timing, and change — adaptability turns luck into wisdom.","mn":"Амьдралын мөчлөг, цаг хугацаа, өөрчлөлт — дасан зохицох чадвар чухал."}},"reading":{"overview":{"en":"Today''s spread centers Wheel of Fortune for leo: a Upright posture invites restorative pause. Keep Reflective energy close while you navigate practical details.","mn":"Өнөөдрийн уншлагад leo-д Хувь тавилангийн хүрд төв байр эзэллээ. Эгц байрлал нь сэргээх түр зогсолт-ыг онцолж байна. Эргэцүүлсэн эрчээ хадгалж, өдөр тутмын зүйлсээ тайван зохицуулаарай."},"love":{"en":"Partnership benefits from small rituals of care. With Wheel of Fortune Upright, restorative pause matters: show up consistently rather than dramatically.","mn":"Харилцаанд халамжийн жижиг үйлдлүүд илүү үнэ цэнтэй. Хувь тавилангийн хүрд Эгц-тэй үед сэргээх түр зогсолт чухал тул огцом үйлдлээс илүү тогтвортой байдал үр дүнтэй."},"career":{"en":"Career momentum favors proof over promises. Wheel of Fortune encourages Upright moves aligned with restorative pause, especially when energy feels Reflective.","mn":"Карьерын өсөлтөд амлалт бус бодит үр дүн илүү чухал. Хувь тавилангийн хүрд нь Эгц алхмуудыг сэргээх түр зогсолт-тай уялдуулахыг зөвлөж байна, ялангуяа энерги Эргэцүүлсэн үед."},"energy":{"en":"Rhythm is shaped by restorative pause. Let clarity and momentum anchor how you spend attention—small wins compound.","mn":"Өдрийн хэмнэл сэргээх түр зогсолт-аар тодорхойлогдоно. тодорхой байдал, урагшлах эрч-ыг анхаарлын төвдөө байлга — жижиг ахицууд нийлж том үр дүн болдог."}}}',63,'2026-05-01 03:11:54','2026-05-01 07:03:54');
INSERT INTO "tarot_daily" VALUES('5eba9c9c-a509-492d-a22f-b6d0ebb93553','2026-05-01','UTC','aries','{"date":"2026-05-01","timezone":"UTC","sign":"aries","card_of_the_day":{"name":"Wheel of Fortune","arcana":"Major","orientation":"Upright","core_meaning":"Cycles turn in your favor; ride the momentum lightly."},"reading":{"overview":"Today, the Wheel of Fortune is on your side today. Aries, cycles turn in your favor; ride the momentum lightly.","love":"Say it plainly. Mystery is not the same as withholding.","career":"Pick one priority you can finish today and let the others wait.","inner_growth":"Pause counts as progress when the foot is heavy.","timing_advice":{"best_window":"morning","id":"aries-2026-05-01","why":"Early energy lands intentions cleanly before the day crowds your attention."},"caution":"Do not confuse heat with truth; check the source.","affirmation":"I lead myself first, then others follow."},"meta":{"energy_score":77,"keywords":["initiative","wheel","courage"],"mood":"Resolute"}}',77,'2026-05-01 03:12:14','2026-05-01 03:12:14');
INSERT INTO "tarot_daily" VALUES('345026ad-7a58-49a9-a555-0729b90b0bd8','2026-05-01','UTC','taurus','{"date":"2026-05-01","timezone":"UTC","sign":"taurus","card_of_the_day":{"name":"Queen of Cups","arcana":"Minor","orientation":"Reversed","core_meaning":"Absorbing other people’s storms."},"reading":{"overview":"Taurus, the reversed Queen of Cups asks for honest pause today. Taurus, absorbing other people’s storms.","love":"Choose the ritual that comforts without numbing.","career":"Make the tedious task an act of mastery, not punishment.","inner_growth":"Stillness sharpens the senses; sit five minutes longer.","timing_advice":{"best_window":"afternoon","id":"taurus-2026-05-01","why":"Mid-day momentum favors collaboration and follow-through."},"caution":"Beware stubbornness disguised as principle.","affirmation":"My pace is my power."},"meta":{"energy_score":66,"keywords":["craft","queen pause","body wisdom"],"mood":"Grounded"}}',66,'2026-05-01 03:12:14','2026-05-01 03:12:14');
