INSERT INTO "tarot_daily" VALUES('45e4650d-8bf3-4217-8b54-bee04b7ffab2','2026-05-01','Asia/Ulaanbaatar','aries','{"copyRev":3,"date":"2026-05-01","timezone":"Asia/Ulaanbaatar","sign":"aries","card_of_the_day":{"name":{"en":"The Hermit","mn":"Даяанч"},"arcana":"Major","orientation":"Upright","core_meaning":{"en":"Reflection, solitude, and inner guidance found away from noise.","mn":"Эргэцүүлэл, ганцаардал, дотоод хариултаа олох үе."}},"reading":{"overview":{"en":"For aries on 2026-05-01 (Asia/Ulaanbaatar), The Hermit appearing Upright frames the day around seasonal shift. The mood leans Reflective, with trust, depth, and courage as quiet threads through your choices.","mn":"2026-05-01 өдөр Asia/Ulaanbaatar бүсэд aries-д Даяанч Эгц-ээр гарсан нь өдрийг үе шатны өөрчлөлт сэдвээр тодорхойлж байна. Өдрийн өнгө Эргэцүүлсэн бөгөөд итгэл, гүнзгий байдал, зориг нь таны сонголтуудад зөөлөн нөлөөлнө."},"love":{"en":"Partnership benefits from small rituals of care. With The Hermit Upright, seasonal shift matters: show up consistently rather than dramatically.","mn":"Харилцаанд халамжийн жижиг үйлдлүүд илүү үнэ цэнтэй. Даяанч Эгц-тэй үед үе шатны өөрчлөлт чухал тул огцом үйлдлээс илүү тогтвортой байдал үр дүнтэй."},"career":{"en":"Work and craft: choose one priority and finish a slice of it. The Hermit in Upright position highlights seasonal shift; keep depth visible in planning.","mn":"Ажил мэргэжил дээр нэг чухал зорилтоо сонгоод тодорхой хэсгийг нь дуусга. Даяанч Эгц байрлалаар үе шатны өөрчлөлт-ыг онцолж байна. Төлөвлөлтдөө гүнзгий байдал-ыг санаж яваарай."},"energy":{"en":"Rhythm is shaped by seasonal shift. Let trust and courage anchor how you spend attention—small wins compound.","mn":"Өдрийн хэмнэл үе шатны өөрчлөлт-аар тодорхойлогдоно. итгэл, зориг-ыг анхаарлын төвдөө байлга — жижиг ахицууд нийлж том үр дүн болдог."}}}',48,'2026-05-01 03:12:14','2026-05-01 07:03:54');
INSERT INTO "tarot_daily" VALUES('476e1f71-725d-4121-b6e9-5d5618e7f081','2026-05-01','Asia/Ulaanbaatar','gemini','{"copyRev":3,"date":"2026-05-01","timezone":"Asia/Ulaanbaatar","sign":"gemini","card_of_the_day":{"name":{"en":"Wheel of Fortune","mn":"Хувь тавилангийн хүрд"},"arcana":"Major","orientation":"Upright","core_meaning":{"en":"Cycles, timing, and change — adaptability turns luck into wisdom.","mn":"Амьдралын мөчлөг, цаг хугацаа, өөрчлөлт — дасан зохицох чадвар чухал."}},"reading":{"overview":{"en":"Today''s spread centers Wheel of Fortune for gemini: a Upright posture invites creative risk. Keep Reflective energy close while you navigate practical details.","mn":"Өнөөдрийн уншлагад gemini-д Хувь тавилангийн хүрд төв байр эзэллээ. Эгц байрлал нь бүтээлч эрсдэл-ыг онцолж байна. Эргэцүүлсэн эрчээ хадгалж, өдөр тутмын зүйлсээ тайван зохицуулаарай."},"love":{"en":"In love and closeness, favor clarity over guessing. Wheel of Fortune suggests Upright pacing—honor your Reflective tone and let openness guide difficult conversations.","mn":"Хайр дурлал, дотно харилцаанд таамаглахаас илүү тодорхой байдлыг сонго. Хувь тавилангийн хүрд нь Эгц хэмнэлийг санал болгож байна. Эргэцүүлсэн байдлаа хадгалж, хэцүү ярианд нээлттэй байдал-ээ дага."},"career":{"en":"Work and craft: choose one priority and finish a slice of it. Wheel of Fortune in Upright position highlights creative risk; keep patience visible in planning.","mn":"Ажил мэргэжил дээр нэг чухал зорилтоо сонгоод тодорхой хэсгийг нь дуусга. Хувь тавилангийн хүрд Эгц байрлалаар бүтээлч эрсдэл-ыг онцолж байна. Төлөвлөлтдөө тэвчээр-ыг санаж яваарай."},"energy":{"en":"Energy today reads as Reflective with a Upright tilt from Wheel of Fortune. Practical tip: pace breaks, hydrate, and protect deep-work windows.","mn":"Өнөөдрийн энерги Эргэцүүлсэн бөгөөд Хувь тавилангийн хүрд-ийн Эгц нөлөө мэдрэгдэнэ. Зөвлөмж: амралтын хэмнэлээ барьж, ус сайн ууж, төвлөрөх цагаа хамгаалаарай."}}}',9,'2026-05-01 03:12:14','2026-05-01 07:03:54');
