INSERT INTO "tarot_daily" VALUES('270ce0e9-0a7d-4457-8467-ef5385687cf8','2026-05-01','Asia/Ulaanbaatar','scorpio','{"copyRev":3,"date":"2026-05-01","timezone":"Asia/Ulaanbaatar","sign":"scorpio","card_of_the_day":{"name":{"en":"The Lovers","mn":"Хосууд"},"arcana":"Major","orientation":"Reversed","core_meaning":{"en":"Choice, alignment, and heartfelt connection rooted in honesty.","mn":"Сонголт, зохицол, үнэнч холбоо."}},"reading":{"overview":{"en":"The calendar reads 2026-05-01; The Lovers (Reversed) asks scorpio to notice how inner alignment shows up in small moments. Keywords: intuition, renewal, openness.","mn":"2026-05-01-ийн энергиэр Хосууд (Урвуу) нь scorpio-д дотоод зохицол жижиг мөчүүдэд хэрхэн илэрч байгааг анзаарахыг сануулж байна. Түлхүүр үгс: зөн совин, шинэчлэл, нээлттэй байдал."},"love":{"en":"Partnership benefits from small rituals of care. With The Lovers Reversed, inner alignment matters: show up consistently rather than dramatically.","mn":"Харилцаанд халамжийн жижиг үйлдлүүд илүү үнэ цэнтэй. Хосууд Урвуу-тэй үед дотоод зохицол чухал тул огцом үйлдлээс илүү тогтвортой байдал үр дүнтэй."},"career":{"en":"Career momentum favors proof over promises. The Lovers encourages Reversed moves aligned with inner alignment, especially when energy feels Bold.","mn":"Карьерын өсөлтөд амлалт бус бодит үр дүн илүү чухал. Хосууд нь Урвуу алхмуудыг дотоод зохицол-тай уялдуулахыг зөвлөж байна, ялангуяа энерги Зоримог үед."},"energy":{"en":"Energy today reads as Bold with a Reversed tilt from The Lovers. Practical tip: pace breaks, hydrate, and protect deep-work windows.","mn":"Өнөөдрийн энерги Зоримог бөгөөд Хосууд-ийн Урвуу нөлөө мэдрэгдэнэ. Зөвлөмж: амралтын хэмнэлээ барьж, ус сайн ууж, төвлөрөх цагаа хамгаалаарай."}}}',31,'2026-05-01 03:12:14','2026-05-01 07:03:54');
