INSERT INTO "tarot_daily" VALUES('9f75bc82-23ba-4abf-b17f-005b037b459b','2026-05-01','Asia/Ulaanbaatar','taurus','{"copyRev":3,"date":"2026-05-01","timezone":"Asia/Ulaanbaatar","sign":"taurus","card_of_the_day":{"name":{"en":"The Tower","mn":"Цамхаг"},"arcana":"Major","orientation":"Reversed","core_meaning":{"en":"Sudden clarity, release of illusion, and rebuilding on truth.","mn":"Гэнэтийн ухаарал, хуурмаг зүйлс нуран унаж, үнэний суурин дээр шинээр эхлэх үе."}},"reading":{"overview":{"en":"For taurus on 2026-05-01 (Asia/Ulaanbaatar), The Tower appearing Reversed frames the day around creative risk. The mood leans Steady, with patience, intuition, and boundaries as quiet threads through your choices.","mn":"2026-05-01 өдөр Asia/Ulaanbaatar бүсэд taurus-д Цамхаг Урвуу-ээр гарсан нь өдрийг бүтээлч эрсдэл сэдвээр тодорхойлж байна. Өдрийн өнгө Тогтуун бөгөөд тэвчээр, зөн совин, хил хязгаар нь таны сонголтуудад зөөлөн нөлөөлнө."},"love":{"en":"Partnership benefits from small rituals of care. With The Tower Reversed, creative risk matters: show up consistently rather than dramatically.","mn":"Харилцаанд халамжийн жижиг үйлдлүүд илүү үнэ цэнтэй. Цамхаг Урвуу-тэй үед бүтээлч эрсдэл чухал тул огцом үйлдлээс илүү тогтвортой байдал үр дүнтэй."},"career":{"en":"Career momentum favors proof over promises. The Tower encourages Reversed moves aligned with creative risk, especially when energy feels Steady.","mn":"Карьерын өсөлтөд амлалт бус бодит үр дүн илүү чухал. Цамхаг нь Урвуу алхмуудыг бүтээлч эрсдэл-тай уялдуулахыг зөвлөж байна, ялангуяа энерги Тогтуун үед."},"energy":{"en":"Energy today reads as Steady with a Reversed tilt from The Tower. Practical tip: pace breaks, hydrate, and protect deep-work windows.","mn":"Өнөөдрийн энерги Тогтуун бөгөөд Цамхаг-ийн Урвуу нөлөө мэдрэгдэнэ. Зөвлөмж: амралтын хэмнэлээ барьж, ус сайн ууж, төвлөрөх цагаа хамгаалаарай."}}}',73,'2026-05-01 07:09:19','2026-05-01 07:09:19');
